const title = String($json.title || '');
const company = String($json.company || '');
const location = String($json.location || '');
const description = String($json.description || '').slice(0, 6000);
const content = `${title}\n${description}`;
let hash = 0;
for (let i = 0; i < content.length; i++) {
  hash = ((hash << 5) - hash) + content.charCodeAt(i);
  hash |= 0;
}
const content_hash = String(hash);

const prompt = `Classify this job listing for a Design careers community (UX, Product Design, UI, Research, Design Ops, Visual/Graphic when digital-product relevant).

Return ONLY a JSON object with exactly these keys:
{
  "is_design_job": boolean,
  "is_international": boolean,
  "confidence": number between 0 and 1,
  "area": string,
  "role": string,
  "discipline": "product_design" | "ux" | "ui" | "ux_research" | "content_design" | "design_ops" | "visual_graphic" | "motion",
  "seniority": "intern" | "junior" | "mid" | "senior" | "lead" | "unknown",
  "work_model": "remote" | "hybrid" | "onsite" | "unknown",
  "employment_type": "clt" | "pj" | "freelance" | "internship" | "unknown",
  "portfolio_required": boolean,
  "skills": string[],
  "tools": string[],
  "summary": string,
  "reason": string
}

Rules:
- is_international=true when the role targets a global/English-speaking market, is outside Brazil-focused hiring, or the listing is primarily in English for an international company.
- summary language: English if is_international=true, otherwise Portuguese (Brazil). Max 3 short sentences for a job card.
- Reject pure software engineering, data science, sales, admin, beauty/fashion retail, physical product packaging, etc. unless clearly a design role.
- Talent pools / "banco de talentos" can still be is_design_job=true if the role is design.
- Reject retail/store manager roles (gerente de loja, vendedor, etc.) even when the mall or neighborhood contains "Design" (e.g. Rio Design Barra, Shopping Rio Design). Those are venue names, not design careers.
- discipline: normalized cargo for mural filters. NEVER use other.
  - product_design: Product/UX+UI hybrid — default for ambiguous roles (VagasUX is UX-focused).
  - ux: explicit UX Designer / experience design in title/role (NOT UX/UI hybrid area alone).
  - ui: ONLY explicit UI Designer / interface design in title/role — strict like motion.
  - ux_research, content_design: specialized.
  - design_ops: Design Ops, program/strategy leadership, strategic design, head/director of design.
  - visual_graphic: graphic/visual/branding/social/print — generic "Designer" title, artes gráficas, social/print in description.
  - motion: ONLY explicit motion designer/design in title/role/area.

JOB:
title: ${title}
company: ${company}
location: ${location}
description:
${description}`;

return {
  json: {
    id: $json.id,
    title,
    company,
    location,
    description,
    content_hash,
    prompt,
  },
};

const job = $('Prepare prompt').item.json;
let ai = $json;

// Gemini shapes: content.parts[].text | text (object/string) | content (string) | raw string
if (ai?.content?.parts?.[0]?.text) {
  ai = ai.content.parts[0].text;
} else if (ai?.candidates?.[0]?.content?.parts?.[0]?.text) {
  ai = ai.candidates[0].content.parts[0].text;
} else if (ai?.text != null) {
  ai = ai.text;
} else if (typeof ai?.content === 'string') {
  ai = ai.content;
}

if (typeof ai === 'string') {
  const cleaned = ai.replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/i, '').trim();
  try { ai = JSON.parse(cleaned); } catch (e) { ai = {}; }
} else if (ai && typeof ai === 'object' && ai.is_design_job === undefined && typeof ai.text === 'string') {
  try { ai = JSON.parse(ai.text); } catch (e) { ai = {}; }
}
if (!ai || typeof ai !== 'object') ai = {};

const seniorityAllow = new Set(['intern','junior','mid','senior','lead','unknown']);
const workAllow = new Set(['remote','hybrid','onsite','unknown']);
const empAllow = new Set(['clt','pj','freelance','internship','unknown']);

const confidence = Math.max(0, Math.min(1, Number(ai.confidence) || 0));

function normalizeJobText(value) {
  return String(value ?? '')
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '');
}

const description = String($('Prepare prompt').item.json.description || '');
const retailText = normalizeJobText(`${job.title} ${ai.role ?? ''} ${ai.area ?? ''} ${description}`);
const explicitDesign =
  /\b(de design|designer|design ops|design system|design de produto|product design|graphic design|visual design|motion design|ux design|ui design|design lead|head of design|gerente de design|coordenador de design|product designer|ux designer|ui designer|ux|ui|research|pesquisa)\b/.test(retailText);
const venueDesign =
  /\b(rio design|shopping .* design|design barra|design leak|boulevard .* design)\b/.test(retailText);
const retailRole =
  /\b(gerente de loja|gerente \| |vendedor|vendedora|operador de loja|supervisor de loja|consultor de vendas|auxiliar de loja|apoio de loja|caixa|estoquista)\b/.test(retailText);
const retailFalsePositive =
  (venueDesign && !explicitDesign) || (retailRole && !explicitDesign);

const shouldPublish = ai.is_design_job === true && confidence >= 0.7 && !retailFalsePositive;
const isInternational = ai.is_international === true;

const seniority = seniorityAllow.has(ai.seniority) ? ai.seniority : 'unknown';
const work_model = workAllow.has(ai.work_model) ? ai.work_model : 'unknown';
const employment_type = empAllow.has(ai.employment_type) ? ai.employment_type : 'unknown';

const DEFAULT_DISCIPLINE = 'product_design';

function normalizeJobText(value) {
  return String(value ?? '').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '');
}
function jobText(input) {
  const description = typeof input.description === 'string' ? input.description.slice(0, 4000) : String(input.description ?? '');
  return normalizeJobText([input.title, input.area, input.role, description].filter(Boolean).join(' '));
}
function headlineText(input) {
  return normalizeJobText([input.title, input.area, input.role].filter(Boolean).join(' '));
}
const MOTION_HEADLINE = /\b(motion designer|motion design|animador ui|ui animation|animacao ui|lottie)\b/;
const VISUAL_HEADLINE = /\b(designer grafico|design grafico|graphic designer|visual designer|branding designer|designer visual|diretor de arte|design editorial|identidade visual|visual\/graphic|brand design|marketing design|design de marketing|design digital|digital design|web design|design web|comunicacao visual|social media|redes sociais|design para midias|performance design|design criativo|designer criativo|designer digital|estagiario de design|estagio em design|material grafico|pecas graficas|midia digital|design de comunicacao|design de conteudo criativo|artes graficas|analista em artes)\b/;
const VISUAL_DESCRIPTION = /\b(redes sociais|social media|instagram|stories|reels|tiktok|facebook ads|google ads|midia paga|performance|crm|e-mail marketing|email marketing|material grafico|pecas graficas|comunicacao visual|identidade visual|branding|impresso|print|folder|banner|flyer|catalogo|packaging|embalagem|campanha publicitaria|marketing digital|materiais de marketing)\b/;
const PRODUCT_HEADLINE = /\b(product design|product designer|ux\/ui|ui\/ux|design de produto|designer de produto|product ux|design system|design de experiencia digital)\b/;
const RESEARCH_HEADLINE = /\b(ux researcher|ux research|user researcher|user research|design researcher|research designer|pesquisador ux|pesquisador de ux|pesquisa com usu|pesquisa de usu|cx researcher|customer experience researcher|head of ux research|research lead|research ops|design research lead|coordenador de pesquisa ux|analista de pesquisa ux)\b/;
const UI_FOCUS_DESCRIPTION = /\b(forte foco em ui|foco em ui|foco principal em ui|primary focus on ui|strong ui focus|focused on ui|olhar apurado para ui|especializado em ui|especialista em ui|high polish ui|acabamento visual)\b/;
const UI_HEADLINE = /\b(ui designer|designer de interface|designer ui|ui design|interface designer|designer de ui)\b/;
const UX_HEADLINE = /\b(ux designer|designer de experiencia|user experience designer|ux design|service design|design de servico|designer ux|designer de ux)\b/;
const CONTENT_HEADLINE = /\b(content design|content designer|ux writing|ux writer|design de conteudo|redator ux|redator de ux|technical writer|writer ux|designer conversacional|conversational designer|conversation designer|design conversacional|chatbot designer|designer de conversacao|content strategist|estrategista de conteudo|copywriter ux|ux copywriter)\b/;
const OPS_STRATEGY_HEADLINE = /\b(design ops|design operations|designops|design program manager|design strategist|strategic designer|design strategy|estrategista de design|head of design|director of design|design director|chief design officer|design operations manager|design operation specialist|design program lead|design excellence|design governance|design maturity)\b/;
function parseDiscipline(value) {
  const normalized = String(value ?? '').trim();
  if (!normalized || normalized === 'other') return null;
  return ["product_design","ux","ui","ux_research","content_design","design_ops","visual_graphic","motion"].includes(normalized) ? normalized : null;
}
function descriptionText(input) {
  const description =
    typeof input.description === 'string'
      ? input.description.slice(0, 4000)
      : String(input.description ?? '')

  return normalizeJobText(description)
}

/** Description mentions social, print, branding, etc. */
function hasGraphicDescriptionFocus(input) {
  return VISUAL_DESCRIPTION.test(descriptionText(input))
}

/** Scope is purely product/UI/UX in headline — not hybrid or generic designer. */
function isExclusiveUiUxProductScope(input) {
  const headline = headlineText(input)
  const area = normalizeJobText(input.area)
  const role = normalizeJobText(input.role)

  if (/product/.test(headline) && /visual|graphic|grafico|brand|marketing|comunicacao|social/.test(headline)) {
    return false
  }
  if (area && /product/.test(area) && /visual|graphic|grafico|brand|marketing|comunicacao/.test(area)) {
    return false
  }

  if (PRODUCT_HEADLINE.test(headline) && !VISUAL_HEADLINE.test(headline)) return true
  if (
    /\b(product designer|design de produto|designer de produto)\b/.test(headline) &&
    !/grafico|graphic|visual|brand|marketing|social/.test(headline)
  ) {
    return true
  }
  if (area && /\bproduct design\b/.test(area) && !/visual|graphic|grafico|brand|marketing|comunicacao/.test(area)) {
    return true
  }
  if (role && /\bproduct designer\b/.test(role) && !/grafico|graphic|visual|brand|marketing/.test(role)) {
    return true
  }

  return false
}

function isGenericDesignerTitle(title) {
  const t = title.replace(/\s+/g, ' ').trim()
  return /^designer(\s*[-–|]\s*(pj|clt|freela|freelance|pleno|pl|junior|jr|senior|sr|júnior|sênior))?\.?\s*$/i.test(t)
}


function isContentDesignJob(input) {
  const headline = headlineText(input)
  const area = normalizeJobText(input.area)
  const role = normalizeJobText(input.role)

  if (
    /\b(product design|product designer|design de produto|designer de produto|design de produtos|coordenador.*design de produto)\b/.test(
      headline,
    ) &&
    !CONTENT_HEADLINE.test(headline)
  ) {
    return false
  }

  if (CONTENT_HEADLINE.test(headline)) return true

  if (
    area &&
    /\b(ux writing|content design|content writing|design de conteudo|conversational design|design conversacional)\b/.test(
      area,
    )
  ) {
    return true
  }

  if (
    role &&
    /\b(ux writer|content designer|technical writer|designer conversacional|conversational designer|redator ux|redator de ux)\b/.test(
      role,
    )
  ) {
    return true
  }

  return false
}



function isUxUiHybridHeadline(headline) {
  return /\b(ux\/ui|ui\/ux|ux ui|ui ux)\b/.test(headline)
}

function isUxResearchJob(input) {
  const headline = headlineText(input)
  const area = normalizeJobText(input.area)
  const role = normalizeJobText(input.role)

  if (
    /\b(product design|product designer|design de produto|designer de produto|designer grafico|design grafico|graphic designer)\b/.test(
      headline,
    ) &&
    !RESEARCH_HEADLINE.test(headline)
  ) {
    return false
  }

  if (RESEARCH_HEADLINE.test(headline)) return true

  if (
    area &&
    /\b(ux research|user research|design research|research ops|pesquisa ux|pesquisa de experiencia)\b/.test(
      area,
    )
  ) {
    return true
  }

  if (
    role &&
    /\b(ux researcher|user researcher|design researcher|research designer|cx researcher|pesquisador ux|pesquisador de ux)\b/.test(
      role,
    )
  ) {
    return true
  }

  return false
}

function hasExplicitUiFocus(input) {
  const headline = headlineText(input)
  const desc = descriptionText(input)

  if (isUxUiHybridHeadline(headline) && !/\|\s*ui\b|\bfoco em ui\b|\(ui\)/.test(headline)) {
    return false
  }

  if (/\|\s*ui\b|\(\s*ui\s*\)|[-–]\s*ui\s*$/.test(headline)) {
    return true
  }

  if (UI_HEADLINE.test(headline) && !isUxUiHybridHeadline(headline)) return true

  if (
    /\b(product designer|product design|designer de produto|design de produto)\b/.test(headline) &&
    UI_FOCUS_DESCRIPTION.test(desc)
  ) {
    return true
  }

  return false
}

function isUiJob(input) {
  const headline = headlineText(input)
  const area = normalizeJobText(input.area)
  const role = normalizeJobText(input.role)

  if (
    /\b(ux\/ui|ui\/ux|ux designer|ux design|designer ux|designer de ux|product design|product designer)\b/.test(
      headline,
    )
  ) {
    return false
  }

  if (UI_HEADLINE.test(headline)) return true

  if (area && /^ui design$|^interface design$|\bui design\b/.test(area) && !/ux/.test(area)) {
    return true
  }

  if (
    role &&
    /\b(ui designer|designer ui|designer de interface|interface designer)\b/.test(role) &&
    !/ux/.test(role)
  ) {
    return true
  }

  return false
}

function isUxJob(input) {
  const headline = headlineText(input)
  const area = normalizeJobText(input.area)
  const role = normalizeJobText(input.role)
  const title = normalizeJobText(input.title)
  const titleRole = `${title} ${role}`.trim()

  if (
    /\b(ux designer|designer ux|designer de ux|designer de experiencia)\b/.test(titleRole) &&
    !/\b(ui designer|designer ui|designer de interface)\b/.test(titleRole)
  ) {
    return true
  }

  if (/\b(ux\/ui|ui\/ux|product design|product designer)\b/.test(headline)) return false
  if (UI_HEADLINE.test(headline) && !UX_HEADLINE.test(headline)) return false

  if (UX_HEADLINE.test(headline)) return true

  if (area && /ux|experience|service/.test(area) && !/visual|graphic|ui design|^ui\b/.test(area)) {
    return true
  }

  if (role && /\b(ux designer|designer ux|designer de ux|designer de experiencia)\b/.test(role)) {
    return true
  }

  return false
}

function isOpsStrategyJob(input) {
  const text = jobText(input)
  const headline = headlineText(input)
  const area = normalizeJobText(input.area)
  const role = normalizeJobText(input.role)

  if (OPS_STRATEGY_HEADLINE.test(text) || OPS_STRATEGY_HEADLINE.test(headline)) return true

  if (
    area &&
    /ops|operations|strategy|strategic|program/.test(area) &&
    /design/.test(area) &&
    !/graphic|visual|grafico|brand|marketing|comunicacao/.test(area)
  ) {
    return true
  }

  if (role && /design ops|designops|design program|design strategist|head of design|design director/.test(role)) {
    return true
  }

  return false
}

function isHybridProductGraphicArea(area) {
  return /product/.test(area) && /visual|graphic|grafico|brand|marketing|comunicacao/.test(area)
}

function isMarketingGraphicHeadline(headline) {
  if (/\b(product design|product designer|design de produto|designer de produto|ux\/ui|ui\/ux|ux designer|ui designer|product ux)\b/.test(headline)) {
    return false;
  }
  if (/\b(publicitario|designer publicitario|designer, publicitario)\b/.test(headline)) return true;
  if (/\bdesigner de marketing\b|\bdesigner de comunicacao\b|\bdesign de marketing\b/.test(headline)) return true;
  if (/\b(marketing|comunicacao)\b/.test(headline) && /\bdesigner\b/.test(headline)) return true;
  if (/\bagencia de marketing\b/.test(headline) && /\bdesigner\b/.test(headline)) return true;
  return false;
}

/** Clearly graphic — not hybrid/ambiguous product+visual (product wins those for VagasUX). */
function isClearlyGraphicJob(input) {
  const headline = headlineText(input)
  const area = normalizeJobText(input.area)
  const role = normalizeJobText(input.role)
  const title = normalizeJobText(input.title)

  if (isMarketingGraphicHeadline(headline)) return true

  if (VISUAL_HEADLINE.test(headline)) return true
  if (role && /grafico|graphic|visual|brand|marketing|comunicacao|criativo/.test(role)) return true

  if (area) {
    if (isHybridProductGraphicArea(area)) return false
    if (/graphic|visual|grafico|brand|marketing|comunicacao|performance|crm/.test(area)) return true
  }

  // Description-driven graphic: social/print focus when headline is not exclusive product/UI/UX
  if (hasGraphicDescriptionFocus(input) && !isExclusiveUiUxProductScope(input)) {
    if (area && isHybridProductGraphicArea(area)) return false
    if (/grafico|graphic|visual|brand|marketing|social/.test(title)) return true
    if (/\bdesigner\b/.test(title) && !/product|ux\/ui|ui\/ux|product designer/.test(title)) {
      return true
    }
  }

  return false
}

function isMotionJob(input) {
  const headline = headlineText(input)
  const area = normalizeJobText(input.area)
  const title = normalizeJobText(input.title)

  if (!MOTION_HEADLINE.test(headline)) return false

  // Hybrid visual/motion: motion only when title/role says motion designer
  if (/\bvisual\/motion\b|\bmotion\/visual\b|\bgraphic\/motion\b|\bgr[aá]fico\/motion\b/.test(area)) {
    return /\bmotion designer\b|\bmotion design\b/.test(title)
  }

  if (/visual|graphic|brand|marketing|comunicacao/.test(area) && !/\bmotion design\b|\bmotion designer\b/.test(area)) {
    return /\bmotion designer\b/.test(title) || /\bmotion designer\b/.test(normalizeJobText(input.role))
  }

  return true
}

function isVisualGraphicJob(input) {
  return isClearlyGraphicJob(input)
}

function inferDisciplineFromJob(input) {
  const text = jobText(input)
  const headline = headlineText(input)
  const area = normalizeJobText(input.area)
  const role = normalizeJobText(input.role)

  if (isUxResearchJob(input)) return 'ux_research'

  if (isContentDesignJob(input)) return 'content_design'

  if (isOpsStrategyJob(input)) return 'design_ops'

  if (area) {
    if (
      /ops|operations|strategy|strategic|program/.test(area) &&
      /design/.test(area) &&
      !/graphic|visual|grafico|brand|marketing|comunicacao/.test(area)
    ) {
      return 'design_ops'
    }
    if (/product/.test(area)) return 'product_design'
    if (/\bmotion design\b|\bmotion designer\b/.test(area)) {
      return isMotionJob(input) ? 'motion' : 'visual_graphic'
    }
    if (/graphic|visual|grafico|brand|marketing|comunicacao|performance|crm|artes graficas/.test(area)) {
      return 'visual_graphic'
    }
    if (/ux\/ui|ui\/ux/.test(area)) {
      const titleRole = `${normalizeJobText(input.title)} ${normalizeJobText(input.role)}`.trim()
      if (isUxUiHybridHeadline(titleRole) || isUxUiHybridHeadline(headline)) {
        if (hasExplicitUiFocus(input)) return 'ui'
        return DEFAULT_DISCIPLINE
      }
      if (
        / (ui designer|designer ui|designer de interface|interface designer) /.test(titleRole) &&
        !/ (ux designer|designer ux|designer de ux|ux\/ui|ui\/ux) /.test(titleRole)
      ) {
        return 'ui'
      }
      if (
        / (ux designer|designer ux|designer de ux|designer de experiencia) /.test(titleRole) &&
        !/ (ui designer|designer ui|designer de interface|ux\/ui|ui\/ux) /.test(titleRole)
      ) {
        return 'ux'
      }
      if (isUiJob(input)) return 'ui'
      if (isUxJob(input)) return 'ux'
      return DEFAULT_DISCIPLINE
    }
    if (/^ui design$|^interface design$|\bui design\b/.test(area) && !/ux/.test(area)) return 'ui'
    if (/experience|service|instructional|learning|\bux\b|cx/.test(area) && !/visual|graphic|ui design/.test(area)) {
      return 'ux'
    }
  }

  if (isMotionJob(input)) return 'motion'

  if (isUxUiHybridHeadline(headline)) {
    if (hasExplicitUiFocus(input)) return 'ui'
    return DEFAULT_DISCIPLINE
  }

  if (hasExplicitUiFocus(input)) return 'ui'

  if (PRODUCT_HEADLINE.test(headline)) return 'product_design'

  if (isVisualGraphicJob(input)) return 'visual_graphic'

  if (isUiJob(input)) return 'ui'

  if (isUxJob(input)) return 'ux'

  if (role) {
    if (/product/.test(role) && !/visual|graphic|marketing/.test(role)) return 'product_design'
    if (/grafico|graphic|visual|brand|marketing|digital|web|criativo|comunicacao|artes graficas/.test(role)) {
      return 'visual_graphic'
    }
    if (/\bmotion designer\b|\bmotion design\b/.test(role)) return 'motion'
    if (/design ops|designops|design program|design strategist|head of design|design director/.test(role)) {
      return 'design_ops'
    }
    if (/\b(ui designer|designer ui|designer de interface|interface designer)\b/.test(role) && !/ux/.test(role)) {
      return 'ui'
    }
    if (/\b(ux designer|designer ux|designer de ux|designer de experiencia)\b/.test(role)) return 'ux'
  }

  if (
    /\b(editor de videos?|video editor|videomaker|audiovisual|edicao de video|producao audiovisual)\b/.test(
      text,
    ) &&
    !MOTION_HEADLINE.test(headline)
  ) {
    return 'visual_graphic'
  }

  const venueOrRetailFalsePositive =
    (/\b(rio design|shopping .* design|design barra|design leak)\b/.test(text) &&
      !/\b(de design|designer|gerente de design|coordenador de design)\b/.test(text)) ||
    (/\b(gerente de loja|gerente \| |vendedor|vendedora|operador de loja|supervisor de loja)\b/.test(
      text,
    ) &&
      !/\b(de design|designer|gerente de design|coordenador de design)\b/.test(text))

  if (venueOrRetailFalsePositive) return DEFAULT_DISCIPLINE

  const titleNorm = normalizeJobText(input.title).replace(/\s+/g, ' ').trim()
  if (isGenericDesignerTitle(titleNorm) && !isExclusiveUiUxProductScope(input)) {
    return DEFAULT_DISCIPLINE
  }

  if (
    /\b(designer|design\b)/.test(text) &&
    !/\b(interior|industrial|moda|fashion|som|sound|acustico|paisag|lighting)\b/.test(text)
  ) {
    return DEFAULT_DISCIPLINE
  }

  return DEFAULT_DISCIPLINE
}

function resolveDiscipline(input) {
  const inferred = inferDisciplineFromJob(input)
  const parsed = parseDiscipline(input.discipline)
  if (!parsed) return inferred

  // Heuristics override IA (motion inflado; product > graphic em casos híbridos/ambíguos)
  if (parsed === 'motion' && inferred !== 'motion') return inferred
  if (parsed === 'ui' && inferred !== 'ui') return inferred
  if (parsed === 'design_ops' && inferred !== 'design_ops') return inferred
  if (parsed === 'content_design' && inferred !== 'content_design') return inferred
  if (parsed === 'ux_research' && inferred !== 'ux_research') return inferred
  if (parsed === 'visual_graphic' && inferred === 'product_design') {
    if (isClearlyGraphicJob(input)) return 'visual_graphic';
    return 'product_design';
  }
  if (parsed === 'product_design' && inferred === 'visual_graphic') return inferred
  if (
    parsed === 'product_design' &&
    (inferred === 'ux' ||
      inferred === 'ui' ||
      inferred === 'motion' ||
      inferred === 'ux_research' ||
      inferred === 'content_design' ||
      inferred === 'design_ops')
  ) {
    return inferred
  }

  return parsed
}

const area = ai.area ? String(ai.area).slice(0, 120) : null;
const role = ai.role ? String(ai.role).slice(0, 120) : null;
const discipline = resolveDiscipline({ discipline: ai.discipline, title: job.title, area, role, description });

const skills = Array.isArray(ai.skills) ? ai.skills.map(String).slice(0, 20) : [];
const tools = Array.isArray(ai.tools) ? ai.tools.map(String).slice(0, 20) : [];

return {
  json: {
    id: job.id,
    is_design_job: ai.is_design_job === true,
    is_international: isInternational,
    ai_confidence: confidence,
    area,
    role,
    discipline,
    seniority,
    work_model,
    employment_type,
    portfolio_required: ai.portfolio_required === true,
    skills,
    tools,
    ai_summary: ai.summary ? String(ai.summary).slice(0, 600) : null,
    ai_reason: ai.reason ? String(ai.reason).slice(0, 600) : null,
    content_hash: job.content_hash,
    enriched_at: new Date().toISOString(),
    status: shouldPublish ? 'published' : 'expired',
  },
};
